import React from 'react';
import { Download, FileText, CheckCircle, X, ShieldAlert } from 'lucide-react';
import jsPDF from 'jspdf';

export default function ExportReportModal({ isOpen, onClose, docData, fileName }) {
  if (!isOpen) return null;

  const exportAsMarkdown = () => {
    if (!docData) return;
    const { summary, riskScore, riskLevel, redFlags, clauses } = docData;

    const mdContent = `# LEGAL RISK & ANALYSIS REPORT: ${summary.title || fileName}

**Generated by LexisAI Counsel**  
**Date:** ${new Date().toLocaleDateString()}  
**Overall Risk Assessment:** ${riskScore}/100 (${riskLevel} RISK)

---

## Executive Summary
- **Document Type:** ${summary.documentType}
- **Parties Involved:** ${summary.parties ? summary.parties.join(' & ') : 'N/A'}
- **Effective Date:** ${summary.effectiveDate}
- **Governing Law:** ${summary.governingLaw}
- **Term Duration:** ${summary.duration}

### Overview
${summary.overview}

---

## Critical Red Flags & Predatory Terms
${redFlags.map(rf => `
### [${rf.severity} RISK] ${rf.title}
- **Quote:** "${rf.clauseQuote}"
- **Risk Explanation:** ${rf.explanation}
- **Negotiation Recommendation:** ${rf.recommendation}
`).join('\n')}

---

## Clause Category Breakdown
${clauses.map(c => `
- **${c.category} (${c.title})**: ${c.analysis} [Status: ${c.riskStatus}]
`).join('\n')}

---
*Disclaimer: LexisAI is an automated legal intelligence assistant. This report is for informational purposes and does not constitute formal attorney-client legal advice.*
`;

    const blob = new Blob([mdContent], { type: 'text/markdown' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `Legal_Report_${(fileName || 'contract').replace(/\.[^/.]+$/, "")}.md`;
    a.click();
    URL.revokeObjectURL(url);
    onClose();
  };

  const exportAsPdf = () => {
    if (!docData) return;
    const { summary, riskScore, riskLevel, redFlags } = docData;

    const doc = new jsPDF();
    doc.setFont("helvetica", "bold");
    doc.setFontSize(20);
    doc.setTextColor(212, 175, 55);
    doc.text("LEXIS AI - LEGAL RISK ASSESSMENT REPORT", 14, 20);

    doc.setFontSize(10);
    doc.setTextColor(100, 116, 139);
    doc.text(`Generated: ${new Date().toLocaleDateString()} | Document: ${fileName || 'Contract'}`, 14, 28);

    doc.setLineWidth(0.5);
    doc.setDrawColor(212, 175, 55);
    doc.line(14, 32, 196, 32);

    doc.setFontSize(14);
    doc.setTextColor(255, 255, 255);
    doc.setFillColor(14, 23, 38);
    doc.rect(14, 38, 182, 20, "F");

    doc.setTextColor(riskLevel === 'HIGH' ? 244 : 16, riskLevel === 'HIGH' ? 63 : 185, 129);
    doc.text(`OVERALL RISK SCORE: ${riskScore} / 100 (${riskLevel} RISK)`, 20, 51);

    let yPos = 70;
    doc.setFontSize(12);
    doc.setTextColor(0, 0, 0);
    doc.text("Executive Summary:", 14, yPos);
    
    doc.setFontSize(10);
    doc.setFont("helvetica", "normal");
    yPos += 8;
    doc.text(`Type: ${summary.documentType}`, 14, yPos);
    yPos += 6;
    doc.text(`Parties: ${summary.parties ? summary.parties.join(' & ') : 'N/A'}`, 14, yPos);
    yPos += 6;
    doc.text(`Jurisdiction: ${summary.governingLaw}`, 14, yPos);

    yPos += 14;
    doc.setFont("helvetica", "bold");
    doc.setFontSize(12);
    doc.text("Critical Red Flags & Recommendations:", 14, yPos);

    redFlags.forEach((rf) => {
      yPos += 10;
      if (yPos > 270) { doc.addPage(); yPos = 20; }
      doc.setFont("helvetica", "bold");
      doc.setFontSize(10);
      doc.setTextColor(220, 38, 38);
      doc.text(`[${rf.severity}] ${rf.title}`, 14, yPos);

      yPos += 6;
      doc.setFont("helvetica", "normal");
      doc.setTextColor(50, 50, 50);
      const recLines = doc.splitTextToSize(`Recommendation: ${rf.recommendation}`, 175);
      doc.text(recLines, 14, yPos);
      yPos += recLines.length * 5;
    });

    doc.save(`Legal_Report_${(fileName || 'contract').replace(/\.[^/.]+$/, "")}.pdf`);
    onClose();
  };

  return (
    <div className="modal-overlay" onClick={onClose}>
      <div className="modal-content" onClick={(e) => e.stopPropagation()}>
        <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1.25rem' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
            <Download size={22} color="var(--accent-gold)" />
            <h3 style={{ fontSize: '1.1rem', fontWeight: '700', color: '#fff' }}>Export Legal Risk Report</h3>
          </div>
          <button style={{ background: 'none', border: 'none', color: 'var(--text-muted)', cursor: 'pointer' }} onClick={onClose}>
            <X size={20} />
          </button>
        </div>

        <p style={{ fontSize: '0.85rem', color: 'var(--text-secondary)', marginBottom: '1.5rem' }}>
          Download a full formal legal analysis report containing risk scores, red flag line quotes, and renegotiation guidance.
        </p>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '1rem', marginBottom: '1.5rem' }}>
          <button
            className="glass-panel"
            style={{ padding: '1.25rem', textAlign: 'center', cursor: 'pointer', border: '1px solid var(--border-gold)' }}
            onClick={exportAsPdf}
          >
            <FileText size={32} color="var(--accent-rose)" style={{ marginBottom: '0.5rem' }} />
            <strong style={{ display: 'block', color: '#fff', fontSize: '0.95rem' }}>PDF Executive Report</strong>
            <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Formatted PDF document</span>
          </button>

          <button
            className="glass-panel"
            style={{ padding: '1.25rem', textAlign: 'center', cursor: 'pointer', border: '1px solid var(--border-color)' }}
            onClick={exportAsMarkdown}
          >
            <FileText size={32} color="var(--accent-blue)" style={{ marginBottom: '0.5rem' }} />
            <strong style={{ display: 'block', color: '#fff', fontSize: '0.95rem' }}>Markdown Report</strong>
            <span style={{ fontSize: '0.75rem', color: 'var(--text-muted)' }}>Editable raw markdown</span>
          </button>
        </div>

        <div style={{ textAlign: 'right' }}>
          <button className="btn-secondary" onClick={onClose}>Close</button>
        </div>
      </div>
    </div>
  );
}
